package com.rezoxnemesis.videostudio;

import android.app.Activity;
import android.os.Bundle;
import android.text.InputType;
import android.view.View;
import android.widget.*;
import org.json.JSONArray;
import org.json.JSONObject;
import java.util.*;
import java.util.concurrent.*;

/** Human controls use the exact same operation facade and immutable artifacts as ChatGPT. */
public final class OpenPipelineActivity extends Activity {
    private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private ProjectStore projects;
    private ProjectStore.Project project;
    private LinearLayout content;
    private TextView status,projectLabel;
    private ProgressBar progress;
    private EditText endpoint,bearer,requestId,controls,resultSha;
    private LinearLayout cogFields;
    private EditText prompt,negativePrompt,width,height,numFrames,fps,seed,steps,guidance,strength;
    private TextView modeDescription;
    private Spinner backend,cogMode;
    private final Map<String,CheckBox> selected=new LinkedHashMap<>();
    private final List<String> templateSourceOrder=new ArrayList<>();
    private boolean templatePinned=false;
    private String templateFailure=null;
    private volatile boolean busy=false,destroyed=false;
    private final List<Button> buttons=new ArrayList<>();
    @Override public void onCreate(Bundle saved){super.onCreate(saved);projects=new ProjectStore(this);String projectId=getIntent().getStringExtra("projectId");project=projectId==null?projects.active():projects.get(projectId);build();initializeTemplate();}
    private TextView label(String text,int size){TextView v=new TextView(this);v.setText(text);v.setTextSize(size);v.setPadding(0,12,0,8);content.addView(v);return v;}
    private EditText field(String hint,String value,boolean multiline){EditText e=new EditText(this);e.setHint(hint);e.setText(value);e.setSingleLine(!multiline);if(multiline){e.setMinLines(4);e.setMaxLines(10);e.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);}content.addView(e,new LinearLayout.LayoutParams(-1,-2));return e;}
    private void button(String text,Runnable callback){Button b=new Button(this);b.setText(text);b.setOnClickListener(v->callback.run());buttons.add(b);content.addView(b,new LinearLayout.LayoutParams(-1,-2));}
    private void build(){ScrollView scroll=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);int pad=(int)(16*getResources().getDisplayMetrics().density);content.setPadding(pad,pad,pad,pad);scroll.addView(content);setContentView(scroll);label("Open Animation Workbench",25);label("Use your own inference computer for Blender or installed open-source models. Drive keeps requests, results and model files; compute must run on your computer.",15);projectLabel=label(project==null?"Open a native project first":project.name+" • source revision "+project.updatedAt,17);
        String configured="";try{configured=new OpenPipelineStore(this).configuration().optString("endpoint","");}catch(Exception ignored){}
        endpoint=field("Your self-hosted HTTPS runner endpoint",configured,false);bearer=field("Runner access token (stored with Android Keystore)","",false);bearer.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);button("Save protected runner connection",()->{String ep=endpoint.getText().toString(),token=bearer.getText().toString();bearer.setText("");operation("open_pipeline_configure",object("endpoint",ep,"bearer",token));});button("Check compute and model readiness",()->operation("open_pipeline_capabilities",new JSONObject()));
        label("Generation request",20);requestId=field("Immutable request ID",UUID.randomUUID().toString(),false);backend=new Spinner(this);backend.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"cogvideox","blender","frame_sequence","interpolation"}));content.addView(backend);modeDescription=label("",14);cogFields=new LinearLayout(this);cogFields.setOrientation(LinearLayout.VERTICAL);content.addView(cogFields);cogMode=new Spinner(this);cogMode.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Text to video","Video to video • MP4 motion reference"}));cogFields.addView(cogMode);prompt=cogInput("Prompt","A quiet mountain lake at sunrise",false);negativePrompt=cogInput("Negative prompt (optional)","",false);strength=cogInput("Video-to-video strength (0.05–1.0)","0.8",true);strength.setEnabled(false);cogMode.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> parent){}public void onItemSelected(AdapterView<?> parent,View view,int position,long id){strength.setEnabled(position==1);if("cogvideox".equals(backend.getSelectedItem()))modeDescription.setText(cogDescription());}});width=cogInput("Width (multiple of 16)","720",true);height=cogInput("Height (multiple of 16)","480",true);numFrames=cogInput("Frames (8k+1)","49",true);fps=cogInput("Frames per second","8",true);seed=cogInput("Seed","42",true);steps=cogInput("Inference steps","20",true);guidance=cogInput("Guidance scale","6.0",true);Button smoke=new Button(this);smoke.setText("Use CPU smoke settings: 64×64, 9 frames, 2 steps");smoke.setOnClickListener(v->{width.setText("64");height.setText("64");numFrames.setText("9");steps.setText("2");if(cogMode.getSelectedItemPosition()==1)strength.setText("0.8");Toast.makeText(this,"Small inference probe; these settings do not establish production quality",Toast.LENGTH_LONG).show();});cogFields.addView(smoke);buttons.add(smoke);controls=field("Generation controls",defaultControls("cogvideox"),true);backend.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> parent){}public void onItemSelected(AdapterView<?> parent,View view,int position,long id){String type=(String)backend.getSelectedItem();boolean cog=type.equals("cogvideox");cogFields.setVisibility(cog?View.VISIBLE:View.GONE);controls.setVisibility(cog?View.GONE:View.VISIBLE);if(!templatePinned||!type.equals("blender")){templatePinned=false;controls.setText(defaultControls(type));}modeDescription.setText(cog?cogDescription():type.equals("blender")?"Blender renders the exact validated timeline. Paste the native cinematic authoring request's timeline and select any original source anchors it names.":type.equals("frame_sequence")?"Encode the ordered, selected project-owned PNG frames. This makes an actual video from your drawings.":"Interpolate an ordered PNG sequence with your configured model. Cut boundaries and end-exclusive hold ranges preserve authored timing.");}});
        label("Explicit source assets",17);label("Select only the assets needed for conditioning or frame sequencing. The request freezes their bytes and source revision.",14);if(project!=null)for(ProjectStore.Asset asset:project.assets){CheckBox checkbox=new CheckBox(this);checkbox.setText(asset.name+" • "+asset.mime);content.addView(checkbox);selected.put(asset.id,checkbox);}
        button("Export immutable request",()->{try{if(templateFailure!=null)throw new IllegalStateException(templateFailure);if(project==null)throw new IllegalStateException("Open a native project first");operation("open_pipeline_export_request",new JSONObject().put("projectId",project.id).put("sourceProjectUpdatedAt",project.updatedAt).put("requestId",requestId.getText().toString().trim()).put("backend",backend.getSelectedItem()).put("controls",generationControls()).put("assetIds",orderedSelectedAssets()));}catch(Exception e){showError(e);}});
        button("Submit to my runner",()->requestAction("open_pipeline_submit"));button("Check job progress",()->requestAction("open_pipeline_status"));button("Cancel this runner job",()->requestAction("open_pipeline_cancel"));button("Download completed result",()->requestAction("open_pipeline_download_result"));button("Import verified output into a new project",()->requestAction("open_pipeline_import_result"));
        label("Linked Drive artifact exchange",20);label("Uses the folder selected in VideoStudio Control. Configure your computer to watch the same Requests folder and publish Results. The phone's folder permission is never sent as a runner credential.",14);button("Archive request to linked folder",()->archive("request"));button("Archive result to linked folder",()->archive("result"));resultSha=field("Completed result SHA-256 from your runner", "", false);button("Restore this request's result from linked folder",()->{String id=requestId.getText().toString().trim();operation("open_pipeline_restore_artifact",object("requestId",id,"name",id+".vsresult","sha256",resultSha.getText().toString().trim()));});button("Show retained requests",()->operation("open_pipeline_list",new JSONObject()));
        progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(100);content.addView(progress);status=label("Ready. Export a request before submitting or exchanging it through Drive.",14);
    }
    private JSONArray orderedSelectedAssets(){JSONArray ids=new JSONArray();Set<String> included=new HashSet<>();for(String id:templateSourceOrder){CheckBox view=selected.get(id);if(view!=null&&view.isChecked()){ids.put(id);included.add(id);}}for(Map.Entry<String,CheckBox> entry:selected.entrySet())if(entry.getValue().isChecked()&&included.add(entry.getKey()))ids.put(entry.getKey());return ids;}
    private void initializeTemplate(){if(!getIntent().hasExtra("requestTemplate")&&!getIntent().hasExtra("requestTemplateFileName")&&!getIntent().hasExtra("requestTemplateSha256"))return;busy=true;for(Button button:buttons)button.setEnabled(false);status.setText("Validating the exact source revision and authored rebuild draft…");final ProjectStore.Project opened=project;worker.submit(()->{try{String raw=OpenPipelineRequestTemplate.readHandoff(getApplicationContext(),getIntent().getStringExtra("requestTemplate"),getIntent().getStringExtra("requestTemplateFileName"),getIntent().getStringExtra("requestTemplateSha256"));ProjectStore.Project current=opened==null?null:projects.get(opened.id);if(opened==null||current==null||opened.updatedAt!=current.updatedAt)throw new IllegalStateException("SOURCE_PROJECT_CHANGED: reopen the cinematic authoring studio");JSONObject accepted=OpenPipelineRequestTemplate.validate(raw,current);runOnUiThread(()->{if(destroyed)return;try{templatePinned=true;backend.setSelection(1);controls.setText(accepted.getJSONObject("controls").toString());requestId.setText(UUID.randomUUID().toString());for(CheckBox checkbox:selected.values())checkbox.setChecked(false);templateSourceOrder.clear();JSONArray ids=accepted.getJSONArray("assetIds");for(int i=0;i<ids.length();i++){String id=ids.getString(i);templateSourceOrder.add(id);selected.get(id).setChecked(true);}status.setText("Authored Blender rebuild draft loaded at source revision "+opened.updatedAt+". Export the request when ready; no render or runner job has been submitted.");}catch(Exception error){templateFailure="Authoring template unavailable; reopen the cinematic authoring studio";showError(error);}});}catch(Exception error){runOnUiThread(()->{templateFailure=error.getMessage()==null?"Invalid authoring template; reopen the cinematic authoring studio":error.getMessage();showError(error);});}finally{runOnUiThread(()->{busy=false;if(!destroyed)for(Button button:buttons)button.setEnabled(true);});}});}
    private EditText cogInput(String hint,String value,boolean number){TextView caption=new TextView(this);caption.setText(hint);cogFields.addView(caption);EditText input=new EditText(this);input.setSingleLine(true);input.setText(value);input.setHint(hint);if(number)input.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);cogFields.addView(input);return input;}
    private String cogDescription(){return (cogMode.getSelectedItemPosition()==1?"Select exactly one project-owned MP4 motion reference. Your runner samples the verified clip at the requested frame clock and uses real CogVideoX video conditioning. Output remains model-generated, with no claim of exact original reconstruction.":"Generate CogVideoX video from text. Select no source assets in this mode.")+" Model files stay on your inference computer or mounted Drive; they are never copied to the phone.";}
    private JSONObject generationControls()throws Exception {if(!"cogvideox".equals(backend.getSelectedItem()))return new JSONObject(controls.getText().toString());boolean video=cogMode.getSelectedItemPosition()==1;JSONObject value=new JSONObject().put("mode",video?"video_to_video":"text_to_video").put("prompt",prompt.getText().toString()).put("width",Integer.parseInt(width.getText().toString())).put("height",Integer.parseInt(height.getText().toString())).put("numFrames",Integer.parseInt(numFrames.getText().toString())).put("fps",Integer.parseInt(fps.getText().toString())).put("seed",Long.parseLong(seed.getText().toString())).put("numInferenceSteps",Integer.parseInt(steps.getText().toString())).put("guidanceScale",Double.parseDouble(guidance.getText().toString()));if(video)value.put("strength",Double.parseDouble(strength.getText().toString()));if(!negativePrompt.getText().toString().isEmpty())value.put("negativePrompt",negativePrompt.getText().toString());return value;}
    private String defaultControls(String type){switch(type){case "frame_sequence":return "{\"fps\":24,\"width\":720,\"height\":1280}";case "interpolation":return "{\"inputFps\":12,\"outputFps\":24,\"cuts\":[],\"hitStopRanges\":[]}";case "blender":return "{\"timeline\":{},\"renderFrames\":24,\"conditioningFrames\":[0]}";default:return "{\"prompt\":\"A quiet mountain lake at sunrise\",\"width\":720,\"height\":480,\"numFrames\":49,\"fps\":8,\"seed\":42,\"numInferenceSteps\":20,\"guidanceScale\":6.0}";}}
    private JSONObject object(String... pairs){JSONObject value=new JSONObject();try{for(int i=0;i<pairs.length;i+=2)value.put(pairs[i],pairs[i+1]);}catch(Exception impossible){throw new IllegalArgumentException("Invalid parameters");}return value;}
    private void requestAction(String action){operation(action,object("requestId",requestId.getText().toString().trim()));}
    private void archive(String kind){operation("open_pipeline_archive_artifact",object("requestId",requestId.getText().toString().trim(),"kind",kind));}
    private void operation(String action,JSONObject p){if(busy)return;busy=true;for(Button button:buttons)button.setEnabled(false);progress.setProgress(0);status.setText("Working…");worker.submit(()->{try{JSONObject result=OpenPipelineOperations.execute(getApplicationContext(),projects,action,p,(n,detail)->runOnUiThread(()->{if(!destroyed){progress.setProgress(n);status.setText(detail);}}));runOnUiThread(()->{if(!destroyed){progress.setProgress(100);status.setText(describe(result));if(result.has("resultSha256"))resultSha.setText(result.optString("resultSha256"));}});}catch(Exception e){runOnUiThread(()->showError(e));}finally{runOnUiThread(()->{busy=false;if(!destroyed)for(Button button:buttons)button.setEnabled(true);});}});}
    private String describe(JSONObject result){StringBuilder text=new StringBuilder();if(result.has("requests")){JSONArray all=result.optJSONArray("requests");if(all!=null)for(int i=0;i<all.length();i++){JSONObject item=all.optJSONObject(i);if(item!=null)text.append(item.optString("requestId")).append(" • ").append(item.optString("backend")).append(" • ").append(item.optString("state")).append('\n');}if(text.length()==0)text.append("No retained generation requests.");return text.toString();}if(result.has("configured")){text.append("Runner connection: ").append(result.optBoolean("credentialReady")?"protected token available":"configure or repair the protected token");if(result.has("reachable"))text.append("\nEndpoint: ").append(result.optBoolean("reachable")?"reachable":"unavailable");JSONObject runtime=result.optJSONObject("runner"),backends=runtime==null?null:runtime.optJSONObject("backends");if(backends!=null){Iterator<String> names=backends.keys();while(names.hasNext()){String name=names.next();JSONObject info=backends.optJSONObject(name);if(info!=null)text.append('\n').append(name).append(": ").append(info.optBoolean("available")?"admitted by runtime":"waiting for model or compute").append(info.isNull("code")?"":" • "+info.optString("code"));}}text.append("\nA completed job must supply verified result bytes before native import.");return text.toString();}for(String key:new String[]{"requestId","backend","state","stage","code","jobId","outputProjectId"})if(result.has(key))text.append(key.equals("sourceProjectUpdatedAt")?"Source revision":key).append(": ").append(result.optString(key)).append('\n');if(result.optBoolean("resultVerified"))text.append("Result archive and declared outputs verified.\n");if(result.optBoolean("imported"))text.append("Cloud result imported into a separate native project.\n");if(result.has("archive"))text.append("Linked-folder archive verified by readback.\n");if(result.has("requestSha256"))text.append("Request SHA-256: ").append(result.optString("requestSha256")).append('\n');if(result.has("resultSha256"))text.append("Result SHA-256: ").append(result.optString("resultSha256")).append('\n');return text.toString();}
    private void showError(Exception error){if(!destroyed&&status!=null)status.setText(error.getMessage()==null?"Operation unavailable":error.getMessage());}
    @Override public void onBackPressed(){if(busy){Toast.makeText(this,"Wait for this verified transfer to finish before leaving",Toast.LENGTH_SHORT).show();return;}super.onBackPressed();}
    @Override protected void onDestroy(){destroyed=true;worker.shutdownNow();super.onDestroy();}
}
